204		}
205		if _, err := s.UpdateDraftBatch("u-second", "B1", "R1", "v2", 3); err != nil {
206			t.Fatalf("第二次调整应成功: %v", err)
207		}
208	
209		// 按后来的计划（R1/v2、3 份）执行、投料并关闭。
210		if _, err := s.StartBatch("s1", "B1"); err != nil {
211			t.Fatalf("开始执行失败: %v", err)
212		}
213		feedTime := time.Date(2026, 10, 1, 9, 30, 0, 0, time.UTC)
214		if _, err := s.AddFeeding("f1", "B1", "M1", "100.5", feedTime, "张三"); err != nil {
215			t.Fatalf("投料 f1 失败: %v", err)
216		}
217		if _, err := s.AddFeeding("f2", "B1", "M4", "2", feedTime.Add(time.Hour), "李四"); err != nil {
218			t.Fatalf("投料 f2 失败: %v", err)
219		}
220		if _, err := s.AddFeeding("f3", "B1", "M1", "50", feedTime.Add(2*time.Hour), "张三"); err != nil {
221			t.Fatalf("投料 f3 失败: %v", err)
222		}
223		if _, err := s.CloseBatch("c1", "B1"); err != nil {
224			t.Fatalf("关闭批次失败: %v", err)
225		}
226	
227		// 关闭后重复提交第一次成功的调整：仍成功返回当时的草稿结果。
228		replay, err := s.UpdateDraftBatch("u-first", "B1", "R1", "v1", 8)
229		if err != nil {
230			t.Fatalf("批次关闭后重放第一次成功的调整仍应成功: %v", err)
231		}
232		checkFirstAdjustView(t, replay)
233	
234		// 实际批次不被历史结果回退：已关闭，保留后来的配方、份数、
235		// 投料顺序与逐物料数量核对。
236		checkClosedBatch := func(got *BatchView) {
237			t.Helper()
238			if got.BatchNo != "B1" || got.RecipeNo != "R1" || got.RecipeVersion != "v2" ||
239				got.RecipeName != "配方改版" || got.PlannedPortions != 3 || got.Status != StatusClosed {
240				t.Fatalf("实际批次应为已关闭的 R1/v2、3 份，得到 %+v", got)
241			}
242			if len(got.Feedings) != 3 {
243				t.Fatalf("应保留 3 条投料，得到 %d 条", len(got.Feedings))
244			}
245			wantFeedings := []FeedingView{
246				{Seq: 1, MaterialNo: "M1", Grams: "100.5", Time: feedTime, Registrar: "张三"},
247				{Seq: 2, MaterialNo: "M4", Grams: "2", Time: feedTime.Add(time.Hour), Registrar: "李四"},
248				{Seq: 3, MaterialNo: "M1", Grams: "50", Time: feedTime.Add(2 * time.Hour), Registrar: "张三"},
249			}
250			for i, want := range wantFeedings {
251				f := got.Feedings[i]
252				if f.Seq != want.Seq || f.MaterialNo != want.MaterialNo || f.Grams != want.Grams ||
253					!f.Time.Equal(want.Time) || f.Registrar != want.Registrar {
254					t.Fatalf("第 %d 条投料应为 %+v，得到 %+v", i+1, want, f)
255				}
256			}
257			mats := materialsMap(got)
258			if len(mats) != 2 {
259				t.Fatalf("已关闭批次只应有 M1、M4 两种物料，得到 %d 项", len(mats))
260			}
261			checkRequirement(t, mats, "M1", "750", "150.5", "-599.5") // 250×3，实投 100.5+50
262			checkRequirement(t, mats, "M4", "6", "2", "-4")           // 2×3
263		}
264		got, err := s.GetBatch("B1")
265		if err != nil {
266			t.Fatalf("查询已关闭批次失败: %v", err)
267		}
268		checkClosedBatch(got)
269	
270		// 重新打开台账后：重放仍返回第一次成功的草稿结果，实际批次仍是已关闭状态。
271		if err := s.Close(); err != nil {
272			t.Fatalf("关闭台账失败: %v", err)
273		}
274		s2, err := Open(dir)
275		if err != nil {
276			t.Fatalf("重新打开台账失败: %v", err)
277		}
278		t.Cleanup(func() { s2.Close() })
279	
280		replay2, err := s2.UpdateDraftBatch("u-first", "B1", "R1", "v1", 8)
281		if err != nil {
282			t.Fatalf("重新打开后重放第一次成功的调整仍应成功: %v", err)
283		}
284		checkFirstAdjustView(t, replay2)
285		got2, err := s2.GetBatch("B1")
286		if err != nil {
287			t.Fatalf("重新打开后查询批次失败: %v", err)
288		}
289		checkClosedBatch(got2)
290	}
291	
292	// 两种拒绝必须区分：
293	//   - 沿用已成功的调整请求编号、却更改调整内容 → ErrRequestConflict；
294	//   - 换用尚未使用的请求编号、对已关闭批次提交相同内容 → ErrInvalidState。
295	// 两种拒绝都保留当前批次，且原成功请求仍可取得原结果。
296	func TestUpdateDraftReplayRejections(t *testing.T) {
297		s := openTestStore(t)
298		registerReplayRecipes(t, s)
299		if _, err := s.CreateBatch("b1", "B1", "R1", "v2", 5); err != nil {
300			t.Fatalf("创建批次失败: %v", err)
301		}
302		if _, err := s.UpdateDraftBatch("u-first", "B1", "R1", "v1", 8); err != nil {
303			t.Fatalf("第一次调整应成功: %v", err)
304		}
305		if _, err := s.UpdateDraftBatch("u-second", "B1", "R1", "v2", 3); err != nil {
306			t.Fatalf("第二次调整应成功: %v", err)
307		}
308		if _, err := s.StartBatch("s1", "B1"); err != nil {
309			t.Fatalf("开始执行失败: %v", err)
310		}
311		if _, err := s.CloseBatch("c1", "B1"); err != nil {
312			t.Fatalf("关闭批次失败: %v", err)
313		}
314	
315		// 同一请求编号、不同调整内容（改了份数）→ ErrRequestConflict。
316		if _, err := s.UpdateDraftBatch("u-first", "B1", "R1", "v1", 9); !errors.Is(err, ErrRequestConflict) {
317			t.Fatalf("同编号不同份数应返回 ErrRequestConflict，得到 %v", err)
318		}
319		// 同一请求编号、不同调整内容（改了配方版本）→ ErrRequestConflict。
320		if _, err := s.UpdateDraftBatch("u-first", "B1", "R1", "v2", 8); !errors.Is(err, ErrRequestConflict) {
321			t.Fatalf("同编号不同配方应返回 ErrRequestConflict，得到 %v", err)
322		}
323		// 新请求编号、相同内容，但批次已关闭 → ErrInvalidState。
324		if _, err := s.UpdateDraftBatch("u-fresh", "B1", "R1", "v1", 8); !errors.Is(err, ErrInvalidState) {
325			t.Fatalf("新编号对已关闭批次提交应返回 ErrInvalidState，得到 %v", err)
326		}
327	
328		// 两种拒绝都不改动当前批次：仍是已关闭的 R1/v2、3 份。
329		got, err := s.GetBatch("B1")
330		if err != nil {
331			t.Fatalf("查询批次失败: %v", err)
332		}
333		if got.RecipeNo != "R1" || got.RecipeVersion != "v2" || got.PlannedPortions != 3 ||
334			got.Status != StatusClosed {
335			t.Fatalf("拒绝后批次应保持已关闭的 R1/v2、3 份，得到 %+v", got)
336		}
337		mats := materialsMap(got)
338		checkRequirement(t, mats, "M1", "750", "0", "-750")
339		checkRequirement(t, mats, "M4", "6", "0", "-6")
340	
341		// 原成功请求仍可取得原结果。
342		replay, err := s.UpdateDraftBatch("u-first", "B1", "R1", "v1", 8)
343		if err != nil {
344			t.Fatalf("拒绝后原成功请求仍应可重放: %v", err)
345		}
346		checkFirstAdjustView(t, replay)
347	}
