628	// 并发：不同请求编号的投料全部生效，互不覆盖。
629	func TestConcurrentFeedings(t *testing.T) {
630		s := openTestStore(t)
631		registerStandardRecipe(t, s, "recipe-1")
632		if _, err := s.CreateBatch("b1", "B1", "R1", "v1", 10); err != nil {
633			t.Fatal(err)
634		}
635		if _, err := s.StartBatch("s1", "B1"); err != nil {
636			t.Fatal(err)
637		}
638	
639		const n = 50
640		var wg sync.WaitGroup
641		errs := make(chan error, n)
642		for i := 0; i < n; i++ {
643			wg.Add(1)
644			go func(i int) {
645				defer wg.Done()
646				_, err := s.AddFeeding(fmt.Sprintf("f-%03d", i), "B1", "M1", "1", time.Now(),
647					fmt.Sprintf("登记人%d", i))
648				errs <- err
649			}(i)
650		}
651		wg.Wait()
652		close(errs)
653		for err := range errs {
654			if err != nil {
655				t.Fatalf("并发投料失败: %v", err)
656			}
657		}
658	
659		got, err := s.GetBatch("B1")
660		if err != nil {
661			t.Fatal(err)
662		}
663		if len(got.Feedings) != n {
664			t.Fatalf("应有 %d 条投料，得到 %d", n, len(got.Feedings))
665		}
666		seqs := map[int]bool{}
667		for _, f := range got.Feedings {
668			if seqs[f.Seq] {
669				t.Fatalf("投料序号重复: %d", f.Seq)
670			}
671			seqs[f.Seq] = true
672		}
673		if len(seqs) != n {
674			t.Fatalf("投料序号应互不相同，得到 %d 个", len(seqs))
675		}
676		if got.Materials[0].ActualGrams != "50" {
677			t.Fatalf("累计实投应为 50，得到 %s", got.Materials[0].ActualGrams)
678		}
679	}
