	if err != nil {
		t.Fatal(err)
	}
	defer s1.Close()
	defer s2.Close()

	if _, err := s1.RegisterRecipe("r1", "R1", "v1", "配方一", []MaterialInput{
		{MaterialNo: "M1", Grams: "1"},
	}); err != nil {
		t.Fatal(err)
	}
