// 已有数据损坏时明确报错，不能当成空台账继续。
func TestCorruptData(t *testing.T) {
	dir := t.TempDir()
	// 先写入有效数据。
	s, err := Open(dir)
	if err != nil {
		t.Fatal(err)
	}
	if _, err := s.RegisterRecipe("r1", "R1", "v1", "配方一", []MaterialInput{
		{MaterialNo: "M1", Grams: "1"},
	}); err != nil {
		t.Fatal(err)
	}
	s.Close()

	// 破坏台账文件。
	if err := os.WriteFile(filepath.Join(dir, "ledger.json"), []byte("{不是合法JSON"), 0o644); err != nil {
		t.Fatal(err)
	}
	if _, err := Open(dir); !errors.Is(err, ErrCorruptData) {
		t.Fatalf("损坏数据应返回 ErrCorruptData，得到 %v", err)
	}

	// 合法 JSON 但版本不受支持。
	if err := os.WriteFile(filepath.Join(dir, "ledger.json"), []byte(`{"version":99,"recipes":[],"batches":[],"requests":{}}`), 0o644); err != nil {
		t.Fatal(err)
	}
	if _, err := Open(dir); !errors.Is(err, ErrCorruptData) {
		t.Fatalf("不支持的版本应返回 ErrCorruptData，得到 %v", err)
	}

	// 空文件不等于“没有台账文件”，按损坏处理，不能当成空台账。
	if err := os.WriteFile(filepath.Join(dir, "ledger.json"), []byte{}, 0o644); err != nil {
		t.Fatal(err)
	}
	s2, err := Open(dir)
	if !errors.Is(err, ErrCorruptData) {
		t.Fatalf("零字节台账应返回 ErrCorruptData，得到 %v", err)
	}
	if s2 != nil {
		s2.Close()
		t.Fatalf("损坏台账不应返回可用的 Store 对象")
	}
	if !strings.Contains(err.Error(), "没有内容") {
		t.Fatalf("错误信息应说明台账文件没有内容，得到 %v", err)
	}
}

// 跨进程并发：两个进程同时向同一台账投料，数据不互相覆盖。
// 本子进程由 TestCrossProcessConcurrent 通过环境变量驱动。
func TestHelperProcess(t *testing.T) {
	if os.Getenv("HELPER_PROCESS") != "1" {
		return
	}
	dir := os.Getenv("HELPER_DIR")
	id := os.Getenv("HELPER_ID")
	s, err := Open(dir)
	if err != nil {
		fmt.Fprintf(os.Stderr, "helper open: %v\n", err)
		os.Exit(1)
	}
	defer s.Close()
	for i := 0; i < 20; i++ {
		if _, err := s.AddFeeding(fmt.Sprintf("f-%s-%03d", id, i), "B1", "M1", "1",
			time.Now(), "登记人"+id); err != nil {
			fmt.Fprintf(os.Stderr, "helper feed: %v\n", err)
			os.Exit(1)
		}
	}
	os.Exit(0)
}

func TestCrossProcessConcurrent(t *testing.T) {
	dir := t.TempDir()
	// 父进程先登记配方，避免与子进程的登记请求竞争同一版本。
	s, err := Open(dir)
	if err != nil {
		t.Fatal(err)
	}
	if _, err := s.RegisterRecipe("recipe-parent", "R1", "v1", "配方一", []MaterialInput{
		{MaterialNo: "M1", Grams: "1"},
	}); err != nil {
		t.Fatal(err)
	}
	if _, err := s.CreateBatch("b-parent", "B1", "R1", "v1", 10); err != nil {
		t.Fatal(err)
	}
	if _, err := s.StartBatch("s-parent", "B1"); err != nil {
		t.Fatal(err)
	}
	s.Close()

	runHelper := func(id string) error {
		cmd := exec.Command(os.Args[0], "-test.run=TestHelperProcess")
		cmd.Env = append(os.Environ(),
			"HELPER_PROCESS=1",
			"HELPER_DIR="+dir,
			"HELPER_ID="+id,
		)
		out, err := cmd.CombinedOutput()
		if err != nil {
			return fmt.Errorf("%v: %s", err, out)
		}
		return nil
	}

	var wg sync.WaitGroup
	errs := make(chan error, 2)
	for _, id := range []string{"A", "B"} {
		wg.Add(1)
		go func(id string) {
			defer wg.Done()
			errs <- runHelper(id)
		}(id)
	}
	wg.Wait()
	close(errs)
	for err := range errs {
		if err != nil {
			t.Fatalf("子进程失败: %v", err)
		}
	}

	s2, err := Open(dir)
	if err != nil {
		t.Fatal(err)
	}
	defer s2.Close()
	got, err := s2.GetBatch("B1")
	if err != nil {
		t.Fatal(err)
	}
	if len(got.Feedings) != 40 {
		t.Fatalf("两个进程共应登记 40 条投料，得到 %d 条（数据被覆盖）", len(got.Feedings))
	}
	seqs := map[int]bool{}
	for _, f := range got.Feedings {
		if seqs[f.Seq] {
			t.Fatalf("投料序号重复: %d", f.Seq)
		}
		seqs[f.Seq] = true
	}
	if got.Materials[0].ActualGrams != "40" {
		t.Fatalf("累计实投应为 40，得到 %s", got.Materials[0].ActualGrams)
	}
}

// 克数精度：三位小数精确计算，不丢精度。
func TestGramsPrecision(t *testing.T) {
	s := openTestStore(t)
	if _, err := s.RegisterRecipe("r1", "R1", "v1", "精度配方", []MaterialInput{
		{MaterialNo: "M1", Grams: "0.001"},
		{MaterialNo: "M2", Grams: "100.123"},
	}); err != nil {
		t.Fatal(err)
	}
	if _, err := s.CreateBatch("b1", "B1", "R1", "v1", 3); err != nil {
		t.Fatal(err)
	}
	if _, err := s.StartBatch("s1", "B1"); err != nil {
		t.Fatal(err)
	}
	// 0.001 + 0.002 = 0.003（浮点下 0.001+0.002 != 0.003）。
	if _, err := s.AddFeeding("f1", "B1", "M1", "0.001", time.Now(), "张三"); err != nil {
		t.Fatal(err)
	}
	if _, err := s.AddFeeding("f2", "B1", "M1", "0.002", time.Now(), "张三"); err != nil {
		t.Fatal(err)
	}
	got, err := s.GetBatch("B1")
	if err != nil {
		t.Fatal(err)
	}
	m := map[string]MaterialRequirement{}
	for _, mm := range got.Materials {
		m[mm.MaterialNo] = mm
	}
	if m["M1"].RequiredGrams != "0.003" || m["M1"].ActualGrams != "0.003" || m["M1"].DifferenceGrams != "0" {
		t.Fatalf("M1 数量核对不正确: %+v", m["M1"])
	}
	if m["M2"].RequiredGrams != "300.369" {
		t.Fatalf("M2 应投量不正确: %+v", m["M2"])
	}
}

package release

import "fmt"

// plannedMaterial 是数量核对规则对配方中一种物料的计算结果：
// 物料编号及其在当前计划份数下的应投量（千分之一克）。
type plannedMaterial struct {
	materialNo    string
	requiredGrams gramsMilli
}

// planRequirements 是批次“应投量核对”数量规则的唯一实现：给定批次采用
// 的配方版本 r 与最终采用的计划份数 portions，按配方中的物料顺序逐项计算
// 每份克数 × 计划份数，返回每种物料的应投量。
//
// 规则对创建批次、调整草稿、读取已保存批次和构造批次查询结果完全一致：
//   - 份数必须为正整数。份数的输入语义由各入口自行处理——创建要求正整数，
//     调整草稿时传 0 表示沿用当前份数（走到这里的必是最终正份数），读取
//     已保存批次时份数非正属于数据损坏；本函数只接受已确定的最终份数；
//   - 结果必须能精确表示到千分之一克：每份克数本身已是千分之一克的整数倍，
//     整数相乘不引入更小单位，不舍入、不截断；
//   - 每种物料分别以 maxGramsMilli（9223372036854775.807 克）为上限：
//     只乘该物料自己的每份克数与份数，不与同批次其他物料的应投量相加，
//     恰好等于上限合法，超过即返回错误。错误信息指出相关物料、配方编号、
//     版本与份数；调用方再按各自场景包装错误分类（提交时为
//     ErrInvalidInput，读取已保存批次时为 ErrCorruptData 并补充批次编号）。
//
// 不能改用同编号配方的其他版本：物料列表与每份克数一律取调用方给定的 r，
// 即批次实际绑定（或本次提交最终选定）的版本。
func planRequirements(r *recipeRecord, portions int) ([]plannedMaterial, error) {
	out := make([]plannedMaterial, 0, len(r.Materials))
	for _, m := range r.Materials {
		required, err := multiplyPortions(m.GramsMilli, portions)
		if err != nil {
			return nil, fmt.Errorf("物料 %q 按配方 %q 版本 %q 以 %d 份计算的应投量不合法: %v",
				m.MaterialNo, r.RecipeNo, r.Version, portions, err)
		}
		out = append(out, plannedMaterial{materialNo: m.MaterialNo, requiredGrams: required})
	}
	return out, nil
}

